def final_score(nums):
    # Sort each row in descending order so we can easily pop the largest remaining element
    sorted_rows = [sorted(row, reverse=True) for row in nums]
    score = 0

    # Continue until all rows are empty
    while any(sorted_rows):
        # Get the largest remaining element from each row that still has elements
        round_picks = []
        for row in sorted_rows:
            if row:
                round_picks.append(row.pop(0))  # pop the largest element
        if round_picks:
            # Add the largest among the picks to the score
            score += max(round_picks)

    return score

